namespace{
int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}

const Id expected_id="00000000-0000-4000-8000-000000000001";
Document normalized(Document d,const Id& generated){if(generated.empty())return d;check(d.collections.size()==3&&d.collections.back().id==generated&&d.collections.back().name=="Created collection"&&d.collections.back().members==std::vector<Id>{"shape","other"},"Exactly one appended non-owning Collection; ID mapping limited to its id");d.collections.back().id=expected_id;return d;}
void same_result(const Session& a,const Session& b,const Id& generated){check(normalized(a.document(),generated)==b.document()&&encode(normalized(a.document(),generated))==encode(b.document())&&normalized(a.preview_document(),generated)==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Complete caller Session/native/History/preview with sole new Collection ID mapping");}
Document fixture(int mode){auto d=empty_document("component-naming-document","comp","art");auto& board=d.compositions.front().artboards.front();board.width=640;board.height=480;for(const auto& id:{Id{"shape"},Id{"peer"},Id{"other"}}){Object object;object.id=id;object.name=id;object.source=default_primitive(id+"-source","nect.shape.rectangle");object.source->parameters.at("width").literal=80;object.source->parameters.at("height").literal=60;object.source->parameters.at("center_x").literal=id=="shape"?320:id=="peer"?180:460;object.source->parameters.at("center_y").literal=240;auto fill=default_operation(id+"-fill","nect.paint.fill");fill.parameters.at("r").literal=id=="shape"?1:0;fill.parameters.at("g").literal=id=="other"?1:0;fill.parameters.at("b").literal=id=="peer"?1:0;object.stack={fill};d.objects.emplace(id,object);}Object group;group.id="group";group.name="Target source";group.kind=Kind::group;group.children={"shape"};d.objects.emplace(group.id,group);Object sibling=group;sibling.id="sibling";sibling.name="Retained source";sibling.children={"peer"};d.objects.emplace(sibling.id,sibling);d.compositions.front().roots={"group","sibling","other"};d.definitions.emplace("definition",Definition{"definition","Twin","group"});d.definitions.emplace("retained",Definition{"retained","Twin","sibling"});Object instance;instance.id="instance";instance.name="Retained instance";instance.kind=Kind::instance;instance.instance=DefinitionInstance{mode==7?"definition":"retained",{}};d.objects.emplace(instance.id,instance);d.compositions.front().roots.push_back(instance.id);d.collections={{"collection","Twin",{"shape","peer"}},{"retained-collection","Twin",{"other"}}};if(mode==8)d.compositions.front().templates.push_back({"template","Retained template","art","definition"});return d;}
void flow(const QString& root,int mode){const bool create=mode>=6,success=mode==4||mode==7,foreign_case=mode==0||mode==5||mode==6;auto initial=fixture(7);valid(initial);auto current=initial;current.objects.at("shape").name="Current source";valid(current);Session base(initial);base.apply({Rename{"shape","Current source"}},0);check(base.document()==current&&base.revision()==1,"Whole independent shared source/Instance/Definition/Collection before Window");auto foreign_initial=initial;foreign_initial.id="foreign-naming-document";foreign_initial.objects.at("shape").source->parameters.at("height").literal=90;foreign_initial.definitions.at("definition").name="Foreign component";foreign_initial.collections.front().members.insert(foreign_initial.collections.front().members.begin(),"other");valid(foreign_initial);auto foreign_current=foreign_initial;foreign_current.objects.at("shape").name="Current source";valid(foreign_current);Session foreign(foreign_initial);foreign.apply({Rename{"shape","Current source"}},0);check(foreign.document()==foreign_current&&foreign.revision()==base.revision()&&foreign.gesture_generation()==base.gesture_generation(),"Complete independent foreign caller with colliding IDs/counters before Window");auto concurrent=base;concurrent.apply({Rename{"shape","Concurrent source"}},1);auto concurrent_doc=current;concurrent_doc.objects.at("shape").name="Concurrent source";valid(concurrent_doc);check(concurrent.document()==concurrent_doc,"Entire concurrent caller before Window");auto busy=base;busy.begin_gesture(1);busy.update_gesture({Set{{"shape","","generator.height"},90}});auto preview=current;preview.objects.at("shape").source->parameters.at("height").literal=90;valid(preview);check(busy.document()==current&&busy.preview_document()==preview,"Entire active caller preview before Window");auto transformed=current;if(create)transformed.collections.push_back({expected_id,"Created collection",{"shape","other"}});else transformed.definitions.at("definition").name="Renamed component";valid(transformed);auto committed=base;if(create)committed.apply({CollectionCommand{CreateCollection{{expected_id,"Created collection",{"shape","other"}}}}},1);else committed.apply({DefinitionCommand{RenameDefinition{"definition","Renamed component"}}},1);check(committed.document()==transformed&&committed.document().objects==current.objects&&committed.document().compositions==current.compositions,"Independent entire naming delta preserves source hierarchy/Instance association before Window");auto history=committed;history.undo(2);check(history.document()==current,"Whole naming Undo before Window");history.redo(3);check(history.document()==transformed&&history.history()==committed.history(),"One History/full naming Redo before Window");auto expected=base;if(foreign_case)expected=foreign;else if(mode==2)expected=concurrent;else if(mode==3)expected=busy;else if(success)expected=committed;const auto prefix=root+"/mode-"+QString::number(mode);write(prefix+"-expected.nect",expected.document());write(prefix+"-expected-preview.nect",expected.preview_document());
QSettings settings(prefix+"-settings.ini",QSettings::IniFormat);settings.setFallbacksEnabled(false);Window w(prefix+"-recovery",std::make_unique<FolderLibrary>(settings,FolderLibrary::PersistOverride{},FolderLibrary::ReadbackOverride{},prefix+"-assets"),&settings);w.host.session=base;w.host.edited();w.resize(1400,1050);w.show();events();w.canvas->set_active_artboard("comp","art",false);w.canvas->set_selections({{"shape",""},{"other",""}});events();auto* actor=w.findChild<QAction*>(create?"create-collection-from-selection":"rename-definition");check(actor&&actor->isEnabled(),"Original component naming action enabled");const auto original_host=w.host.session_id;QString callback_error;int stages=0;
const auto step=[&](int stage){try{auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget());check(dialog&&dialog->windowTitle()==(create?"Create Collection":"Rename Definition"),"Original naming modal exact");++stages;if(!create&&stage==0){auto* choices=dialog->findChild<QComboBox*>();check(choices&&choices->count()==2&&choices->itemText(0)=="Twin · definition"&&choices->itemText(1)=="Twin · retained","Duplicate component names disambiguated by original stable IDs");choices->setCurrentIndex(0);if(mode==0)w.host.session=foreign;check(dialog->grab().save(prefix+"-choice.png"),"Actual original Definition choice before acceptance");dialog->accept();}else{if(!create)check(dialog->textValue()=="Twin","Original source name captured independent of later caller");dialog->setTextValue(create?"Created collection":"Renamed component");if(mode==5||mode==6)w.host.session=foreign;else if(mode==1)w.host.session_id+="-changed";else if(mode==2)w.host.session=concurrent;else if(mode==3)w.host.session=busy;check(dialog->grab().save(prefix+"-dialog.png"),"Actual original name dialog before acceptance");dialog->accept();}}catch(const std::exception& e){callback_error=QString::fromUtf8(e.what());if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();}};
QTimer::singleShot(0,&w,[&]{step(0);if(!create&&callback_error.isEmpty())QTimer::singleShot(0,&w,[&]{step(1);});});actor->trigger();events();check(callback_error.isEmpty()&&stages==(create?1:2),"All original naming stages complete without fixture exception");const auto observed=w.host.session;const auto status=w.statusBar()->currentMessage();Id generated;if(mode==7){check(observed.document().collections.size()==3,"Exactly one Collection created");generated=observed.document().collections.back().id;check(generated.size()==36&&generated!=expected_id,"Original new UUID observed independently");}write(prefix+"-observed.nect",observed.document());write(prefix+"-observed-preview.nect",observed.preview_document());const auto actual=normalized(observed.document(),generated),actual_preview=normalized(observed.preview_document(),generated);write(prefix+"-normalized.nect",actual);write(prefix+"-normalized-preview.nect",actual_preview);check(w.grab().save(prefix+"-window.png"),"Whole original naming result before Save");QJsonObject v{{"mode",mode},{"status",status},{"generated_id",QString::fromStdString(generated)},{"document_equal",actual==expected.document()},{"preview_equal",actual_preview==expected.preview_document()},{"history_equal",observed.history()==expected.history()},{"artwork_equal",observed.document().objects==expected.document().objects&&observed.document().compositions==expected.document().compositions},{"revision",qint64(observed.revision())},{"gesture_active",observed.gesture_active()},{"gesture_generation",qint64(observed.gesture_generation())},{"caller_identity_preserved",mode!=3||observed.gesture_identity()==busy.gesture_identity()},{"host_equal",mode==1?w.host.session_id!=original_host:w.host.session_id==original_host},{"view_equal",w.canvas->selected_objects()==std::vector<Id>{"shape","other"}&&w.canvas->active_composition()=="comp"&&w.canvas->active_artboard()=="art"},{"save_intent",mode!=3}};QFile metadata(prefix+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Immutable complete naming caller readback before Save");metadata.write(QJsonDocument(v).toJson());metadata.close();same_result(observed,expected,generated);check(v["view_equal"].toBool()&&v["host_equal"].toBool()&&v["caller_identity_preserved"].toBool()&&v["artwork_equal"].toBool(),"Caller source/hierarchy/Instance/view/gesture preserved");if(mode==0||mode==1||mode==2||mode==5||mode==6)check(status.startsWith("REVISION_CONFLICT:"),"Naming caller refusal explicit");if(mode==3)check(status.startsWith("GESTURE_ACTIVE:"),"Active caller naming refusal explicit");if(success){check(status.startsWith(create?"Collection created":"Definition renamed"),"Current original naming success explicit");w.host.session.undo(2);check(w.host.session.document()==current,"Actual complete naming Undo");w.host.session.redo(3);check(normalized(w.host.session.document(),generated)==transformed,"Actual complete naming Redo");w.host.session=observed;}if(mode!=3){w.host.save(prefix+"-saved.nect");w.host.flush();events();same_result(w.host.session,expected,generated);check(read(prefix+"-saved.nect")==read(prefix+"-observed.nect")&&normalized(decode(read(prefix+"-saved.nect").toStdString()),generated)==expected.document()&&QFile::copy(prefix+"-saved.nect",prefix+"-snapshot.nect"),"Whole raw Save/snapshot preserved; only new Collection id mapped");}w.close();events();}
}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);app.setStyle("Fusion");app.setStyleSheet(application_style_sheet());std::cout.setf(std::ios::unitbuf);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<" original Definition Rename/Collection Create; physical/clipboard/fonts NOT_RUN\n";QTemporaryDir temp;check(temp.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_COMPONENT_NAMING_DOCUMENT_ROOT"),root=requested.isEmpty()?temp.path():requested;int failures=0;for(int mode=0;mode<8;++mode){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Component naming Document cases failed: "+std::to_string(failures));std::cout<<"PASS Component naming Document "<<checks<<" checks\n";QTest::qWait(300);return 0;}catch(const std::exception& e){std::cerr<<"FAIL Component naming Document "<<e.what()<<" after "<<checks<<" checks\n";QTest::qWait(300);return 1;}}
